    /**
     * Dep Arr Page
     */
    class DepArrPage extends FmcPage {
        constructor() {
            super(...arguments);
            this.store = new DepArrPageStore();
            this.controller = new DepArrPageController(this.eventBus, this.fms, this.store, this);
            this.primaryOrigin = new DisplayField(this, {
                formatter: IcaoIdentFormatter,
            });
            this.primaryDestination = new DisplayField(this, {
                formatter: IcaoIdentFormatter,
            });
        }
        /** @inheritDoc */
        onInit() {
            this.primaryOrigin.bind(this.store.origin);
            this.primaryDestination.bind(this.store.destination);
            this.controller.currentCoreView.sub((view) => { this.changePage(view); });
            this.primaryOrigin.getOptions().style = '[green]';
            this.primaryDestination.getOptions().style = '[green]';
        }
        /** @inheritDoc */
        onPause() {
            this.controller.destroy();
        }
        /** @inheritDoc */
        onResume() {
            this.controller.init();
            const { viewToShow } = this.router.params;
            let view = viewToShow ? viewToShow : DepArrView.DEP;
            if (view === DepArrView.DEP) {
                this.controller.displayDeparture();
            }
            else if (view === DepArrView.ARR) {
                this.controller.displayArrival();
            }
        }
        /** @inheritDoc */
        onPageButtonPressed() {
            this.controller.currentCoreView.set(DepArrView.INDEX);
        }
        /**
         * Method to Update When Changing Pages
         * @param view The new view
         */
        changePage(view) {
            if (view !== DepArrView.INDEX) {
                this.store.loadCurrentProcedureData(this.fms, this.controller.currentCoreView.get());
            }
            this.invalidate();
        }
        /** @inheritDoc */
        render() {
            switch (this.controller.currentCoreView.get()) {
                case DepArrView.INDEX:
                    return [this.getIndexTemplate()];
                case DepArrView.ARR:
                case DepArrView.DEP:
                    return [this.controller.renderDepArrTemplate()];
            }
        }
        /** @inheritDoc */
        async handleSelectKey(event) {
            if (this.controller.currentCoreView.get() === DepArrView.INDEX) {
                if (event === FmcSelectKeysEvent.LSK_1 && this.fms.facilityInfo.originFacility) {
                    this.controller.displayDeparture();
                    return true;
                }
                else if (event === FmcSelectKeysEvent.RSK_2 && this.fms.facilityInfo.destinationFacility) {
                    this.controller.displayArrival();
                    return true;
                }
            }
            return false;
        }
        /**
         * Handles paging for the dep/arr page
         * @param event The FmcPrevNextEvent
         * @returns whether this was handled.
         */
        handleScrollKey(event) {
            if (this.controller.currentCoreView.get() !== DepArrView.INDEX) {
                const currentPage = this.controller.currentPage.get();
                const pageCount = this.controller.pageCount.get();
                if (event === FmcPrevNextEvent.BTN_NEXT) {
                    if (currentPage < pageCount) {
                        this.controller.currentPage.set(currentPage + 1);
                    }
                    else {
                        this.controller.currentPage.set(1);
                    }
                }
                else if (event === FmcPrevNextEvent.BTN_PREV) {
                    if (currentPage > 1) {
                        this.controller.currentPage.set(currentPage - 1);
                    }
                    else {
                        this.controller.currentPage.set(pageCount);
                    }
                }
            }
            return true;
        }
        /**
         * Returns the Index template
         * @returns the Index Template
         */
        getIndexTemplate() {
            return [
                ['', '', 'DEP/ARR INDEX[white]'],
                ['', '', ''],
                ['<DEP', '', this.primaryOrigin],
                ['', ''],
                ['', 'ARR>', this.primaryDestination],
                // ['', '', 'SEC FPLN[blue]'],
                ['', '', ''],
                ['', ''],
                // [' DEP', 'ARR ', 'OTHER'],
                ['', '', ''],
                // ['<----', '---->'],
                ['', ''],
            ];
        }
        /** @inheritDoc */
        setActiveRoute(routeString) {
            this.router.activeRouteSubject.set(routeString);
        }
    }

