    /** FMC format for fuel flow */
    class TotalFuelFlowFormat {
        constructor() {
            this.nullValueString = '---';
        }
        /** @inheritdoc */
        format(ff) {
            let isMetric = WT21UnitsUtils.getIsMetric();
            return (isMetric) ? `${(Math.floor(ff / 10) * 10 / 2.205).toFixed(0)}[blue]` : `${(Math.floor(ff / 10) * 10).toFixed(0)}[blue]`;
        }
    }
    /** FMC format for ground speed */
    class GroundSpeedFormat {
        constructor() {
            this.nullValueString = '---';
        }
        /** @inheritdoc */
        format(gs) {
            return `${gs.toFixed(0)}[blue]`;
        }
    }
    class SpecificRangeFormat {
        constructor() {
            this.nullValueString = '---';
        }
        /** @inheritdoc */
        format(v) {
            let isMetric = WT21UnitsUtils.getIsMetric();
            if (isNaN(v) || v === Infinity) {
                return `---${isMetric ? 'NM/KG' : 'NM/LB'}[blue]`;
            }
            return `${v.toFixed(3)}${isMetric ? 'NM/KG' : 'NM/LB'}[blue]`;
        }
    }
    class FuelMgmtPage extends FmcPage {
        constructor() {
            super(...arguments);
            this.perfInitLink = PageLinkField.createLink(this, '<PERF INIT', '/vnav-setup');
            this.perfDataLink = PageLinkField.createLink(this, 'PERF DATA>', '/perf-data');
            this.engEventsSub = this.eventBus.getSubscriber();
            this.clockEventsSub = this.eventBus.getSubscriber();
            this.gnssEventsSub = this.eventBus.getSubscriber();
            this.adc = this.eventBus.getSubscriber();
            this.ffLeftConsumer = this.engEventsSub.on('fuel_flow_1').atFrequency(1);
            this.ffRightConsumer = this.engEventsSub.on('fuel_flow_2').atFrequency(1);
            this.ffTotalConsumer = this.engEventsSub.on('fuel_flow_total').atFrequency(1);
            this.fuelQtyTotalConsumer = this.engEventsSub.on('fuel_total').whenChangedBy(1);
            this.fuelQtyLeftConsumer = this.engEventsSub.on('fuel_left').whenChangedBy(1);
            this.fuelQtyRightConsumer = this.engEventsSub.on('fuel_right').whenChangedBy(1);
            this.fuelQtyLeftSubject = msfsSdk.Subject.create(0);
            this.fuelQtyRightSubject = msfsSdk.Subject.create(0);
            this.gsConsumer = this.gnssEventsSub.on('ground_speed').whenChanged();
            this.trueAirSpeed = this.adc.on('tas').whenChanged();
            this.ffLeftSubject = msfsSdk.Subject.create(0);
            this.ffRightSubject = msfsSdk.Subject.create(0);
            this.ffTotalSubject = msfsSdk.Subject.create(0);
            this.fuelQtySubject = msfsSdk.Subject.create(0);
            this.currentGSSubject = msfsSdk.Subject.create(null);
            this.perfTripGSSubject = msfsSdk.Subject.create(0);
            this.currentTasSubject = msfsSdk.Subject.create(null);
            this.timeToReserveSubject = msfsSdk.Subject.create(null);
            this.rangeToReserveSubject = msfsSdk.Subject.create(null);
            this.specificRangeSubject = msfsSdk.Subject.create(null);
            this.specificTasRangeSubject = msfsSdk.Subject.create(null);
            this.fuelQtyField = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }, '---', () => "blue"),
            }).bind(this.fuelQtySubject);
            this.ffLeftField = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }),
            }).bind(this.ffLeftSubject);
            this.ffRightField = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }),
            }).bind(this.ffRightSubject);
            this.fuelFlowTotalField = new DisplayField(this, {
                formatter: new TotalFuelFlowFormat(),
            }).bind(this.ffTotalSubject);
            this.ffTotal2Field = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }),
            }).bind(this.ffTotalSubject);
            this.fuelUsedLeftField = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }),
            }).bind(this.baseInstrument.flightLogger.fuelUsedLeft);
            this.fuelUsedRightField = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }),
            }).bind(this.baseInstrument.flightLogger.fuelUsedRight);
            this.fuelUsedTotalField = new DisplayField(this, {
                formatter: new ConvertableNumberAndUnitFormat(msfsSdk.UnitType.POUND, msfsSdk.UnitType.KILOGRAM, { padStart: 4, minValue: 0, showUnit: false }),
            }).bind(this.baseInstrument.flightLogger.fuelUsedTotal);
            this.specificRangeField = new DisplayField(this, {
                formatter: new SpecificRangeFormat(),
            }).bind(this.specificRangeSubject);
            this.specificTasRangeField = new DisplayField(this, {
                formatter: new SpecificRangeFormat(),
            }).bind(this.specificTasRangeSubject);
            this.groundSpeedField = new DisplayField(this, {
                formatter: new GroundSpeedFormat(),
            }).bind(this.currentGSSubject);
            this.tureSpeedField = new DisplayField(this, {
                formatter: new GroundSpeedFormat(),
            }).bind(this.currentTasSubject);
        }
        onResume() {
            super.onResume();
        }
        /**
         * A method for converting a number to the tens precision.
         * @param value The passed value
         * @returns The value but to the tens precision
         */
        getTensPrecision(value) {
            return (Math.floor(value / 10) * 10);
        }
        /** @inheritdoc */
        onInit() {
            // fuel flow
            this.addBinding(new Binding(this.ffLeftConsumer, (v) => {
                this.ffLeftSubject.set(this.getTensPrecision(msfsSdk.UnitType.GALLON_FUEL.convertTo(v, msfsSdk.UnitType.POUND)));
            }));
            this.addBinding(new Binding(this.ffRightConsumer, (v) => {
                this.ffRightSubject.set(this.getTensPrecision(msfsSdk.UnitType.GALLON_FUEL.convertTo(v, msfsSdk.UnitType.POUND)));
            }));
            this.addBinding(new Binding(this.ffTotalConsumer, (v) => {
                this.ffTotalSubject.set(this.getTensPrecision(msfsSdk.UnitType.GALLON_FUEL.convertTo(v, msfsSdk.UnitType.POUND)));
            }));
            this.addBinding(new Binding(this.fuelQtyTotalConsumer, (v) => {
                this.fuelQtySubject.set(this.getTensPrecision(msfsSdk.UnitType.GALLON_FUEL.convertTo(v, msfsSdk.UnitType.POUND)));
            }));
            this.addBinding(this.clockEventsSub.on('simTime').atFrequency(1).handle(this.computeValues.bind(this)));
            this.addBinding(new Binding(this.gsConsumer, (v) => {
                this.currentGSSubject.set(v > 0 ? v : null);
                this.perfTripGSSubject.set(v);
            }));
            this.addBinding(new Binding(this.trueAirSpeed, (v) => {
                this.currentTasSubject.set(v > 40 ? v : 0);
            }));
            this.addBinding(new Binding(this.fuelQtyLeftConsumer, (v) => {
                this.fuelQtyLeftSubject.set(this.getTensPrecision(msfsSdk.UnitType.GALLON_FUEL.convertTo(v, msfsSdk.UnitType.POUND)));
            }));
            this.addBinding(new Binding(this.fuelQtyRightConsumer, (v) => {
                this.fuelQtyRightSubject.set(this.getTensPrecision(msfsSdk.UnitType.GALLON_FUEL.convertTo(v, msfsSdk.UnitType.POUND)));
            }));
        }
        /**
         * Computes and updates the fuel based calcs.
         */
        computeValues() {
            var _a, _b, _c;
            const reserveFuel = (_a = this.fms.performancePlanProxy.reserveFuel.get()) !== null && _a !== void 0 ? _a : 0;
            const fuelToReserve = this.fms.basePerformanceManager.sensedFuelWeight.get() - reserveFuel;
            const timeToReserve = 60 * (fuelToReserve / this.ffTotalSubject.get());
            this.timeToReserveSubject.set(timeToReserve);
            const gs = (_b = this.perfTripGSSubject.get()) !== null && _b !== void 0 ? _b : 0;
            const rangeToReserve = (timeToReserve / 60) * gs;
            this.rangeToReserveSubject.set(rangeToReserve);
            const fuelFlowTotal = WT21UnitsUtils.getIsMetric() ? msfsSdk.UnitType.POUND.convertTo(this.ffTotalSubject.get(), msfsSdk.UnitType.KILOGRAM) : this.ffTotalSubject.get();
            const specificRange = ((1 / fuelFlowTotal) * gs);
            const tas = (_c = this.currentTasSubject.get()) !== null && _c !== void 0 ? _c : 0;
            const specificTasRange = ((1 / fuelFlowTotal) * tas);
            this.specificRangeSubject.set(specificRange);
            this.specificTasRangeSubject.set(specificTasRange);
        }
        /** @inheritDoc */
        render() {
            const isMetric = WT21UnitsUtils.getIsMetric();
            const title = isMetric ? 'FUEL MGT-KG[white]' : 'FUEL MGT-LB[white]';
            return [
                [
                    ['', this.PagingIndicator, title],
                    [' FUEL[white]', 'FUEL FLOW[white] '],
                    [this.fuelQtyField, this.fuelFlowTotalField],
                    [' GRD', 'TRUE ', '<---SPEED--->'],
                    [this.groundSpeedField, this.tureSpeedField],
                    [' GRD', 'AIR ', '<---SP RNG--->'],
                    [this.specificRangeField, this.specificTasRangeField],
                    [this.perfInitLink, this.perfDataLink]
                ],
                [
                    ['', this.PagingIndicator, title],
                    [' ENG', 'USED', 'FLOW<-FUEL->'],
                    ['   1', this.fuelUsedLeftField, this.ffLeftField],
                    ['', '', ''],
                    ['   2', this.fuelUsedRightField, this.ffRightField],
                    ['', '', ''],
                    [' TOTAL', this.fuelUsedTotalField, this.ffTotal2Field],
                    [this.perfInitLink, this.perfDataLink]
                ],
            ];
        }
    }

    /**
     * FMC Component for HOLD LIST entry
     */
    class HoldListEntry extends FmcComponent {
        /**
         * Ctor
         *
         * @param page    {@link FmcPage} containing this component
         * @param options options for the component
         */
        constructor(page, options) {
            super(page, options);
            this.options = options;
        }
        /** @inheritDoc */
        render() {
            return `<${this.options.legIdent}`;
        }
        /** @inheritDoc */
        async onHandleSelectKey() {
            this.page.setActiveRoute('/fpln-hold', { atLeg: this.options.legPlanIndex });
            return true;
        }
    }
    /**
     * ACT HOLD LIST page
     */
    class HoldListPage extends FmcPage {
        constructor() {
            super(...arguments);
            this.FlightPlanHolds = msfsSdk.Subject.create([]);
        }
        /** @inheritDoc */
        init() {
            this.addBinding(this.FlightPlanHolds.sub(() => this.invalidate()));
        }
        /** @inheritDoc */
        render() {
            return [
                [
                    ['', '', 'HOLDING PATTERN'],
                    [''],
                    ...this.renderHoldRows(),
                ]
            ];
        }
        /** @inheritDoc */
        async handleSelectKey(event) {
            if (event === FmcSelectKeysEvent.RSK_4) {
                this.setActiveRoute('/route', { isForHoldSelection: true }); // TODO Temporary
                return true;
            }
            return false;
        }
        /**
         * Renders all row for showing holds in flight plan
         *
         * @returns a list of template rows
         */
        renderHoldRows() {
            const allFlightPLanHolds = WT21FmsUtils.getPlanHolds(this.fms.getPlanForFmcRender());
            const rows = [];
            for (let i = 0; i < Math.min(3, allFlightPLanHolds.length); i++) {
                const hold = allFlightPLanHolds[i];
                const holdPlanIndex = this.fms.getPlanForFmcRender().getLegIndexFromLeg(hold);
                const component = new HoldListEntry(this, {
                    legIdent: hold.leg.fixIcao === msfsSdk.ICAO.emptyIcao ? 'PPOS' : msfsSdk.ICAO.getIdent(hold.leg.fixIcao),
                    legPlanIndex: holdPlanIndex
                });
                rows.push([component], ['']);
            }
            while (rows.length < 3 * 2) {
                rows.push(['']);
            }
            rows[5][1] = 'NEW HOLD>';
            return rows;
        }
    }

