    NavIdentPageDateFormatter.MONTH_NAMES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
    class NavIdentPage extends FmcPage {
        constructor() {
            super(...arguments);
            this.navDbDate = msfsSdk.ComputedSubject.create(SimVar.GetGameVarValue('FLIGHT NAVDATA DATE RANGE', 'string'), (value) => {
                const matches = value.match(NavIdentPage.WT21_NAVDATA_REGEX);
                if (matches) {
                    const [, fromMonth, fromDay, toMonth, toDay, year] = matches;
                    return `${fromDay}${fromMonth}${year} ${toDay}${toMonth}${year}`;
                }
                return value;
            });
            this.indexPageLink = PageLinkField.createLink(this, '<MAINTENANCE', '/');
            this.posInitLink = PageLinkField.createLink(this, 'POS INIT>[blackwhite]', '/pos-init');
            this.isNavDbValid = msfsSdk.Subject.create(true);
            this.SimTimeConsumer = msfsSdk.ConsumerSubject.create(this.eventBus
                .getSubscriber()
                .on('simTime')
                .atFrequency(NavIdentPage.CLOCK_UPDATE_FREQUENCY, true), Date.now()).map((value) => new Date(value));
            this.ClockField = new DisplayField(this, {
                formatter: TimeFormatter,
            });
            this.DateField = new DisplayField(this, {
                formatter: new NavIdentPageDateFormatter(),
            });
            this.NavDbDateField = new DisplayField(this, {
                formatter: RawFormatter,
            });
        }
        /** @inheritDoc */
        init() {
            this.ClockField.bind(this.SimTimeConsumer);
            this.ClockField.getOptions().style = '[blue]';
            this.DateField.bind(this.SimTimeConsumer);
            this.DateField.getOptions().style = '[blue]';
            this.NavDbDateField.bind(this.navDbDate);
            this.addBinding(new Binding(this.isNavDbValid, (isValid) => {
                this.NavDbDateField.getOptions().style = isValid ? '' : '[orange]';
                this.invalidate();
            }));
            this.addBinding(new Binding(this.SimTimeConsumer, (value) => {
                const navDbDate = this.getDatesFromNavDbString(this.navDbDate.getRaw());
                const datenow = new Date(value).setHours(0, 0, 0, 0);
                this.isNavDbValid.set((datenow >= navDbDate[0].getTime()) && (datenow <= navDbDate[1].getTime()));
            }));
        }
        /**
         * Get date objects from nav data string
         * @param navDbString The nav data string.
         * @returns An array of From and To date.
         */
        getDatesFromNavDbString(navDbString) {
            const matches = navDbString.match(NavIdentPage.WT21_NAVDATA_REGEX);
            const getMonth = (month) => {
                return (NavIdentPageDateFormatter.MONTH_NAMES.indexOf(month));
            };
            if (matches) {
                const [, fromMonth, fromDay, toMonth, toDay, year] = matches;
                const yearStr = parseInt(`20${year}`);
                return [new Date(yearStr, getMonth(fromMonth), parseInt(fromDay)), new Date(yearStr, getMonth(toMonth), parseInt(toDay))];
            }
            const now = new Date();
            return [now, now];
        }
        // eslint-disable-next-line jsdoc/require-jsdoc
        render() {
            return [
                [
                    ['', '1/1[white page-number-text]', 'NAV IDENT[white]'],
                    [' DATE[white]', 'ACTIVE NDB[white] '],
                    [this.DateField, this.NavDbDateField],
                    [' UTC[white]'],
                    [this.ClockField, this.NavDbDateField],
                    [' SW[white]', 'NDB V3.00 16M[white] '],
                    ['NZ5.2[green]', 'WORLD3- 03[green]'],
                    [this.indexPageLink, this.posInitLink]
                ]
            ];
        }
    }
