    /**
     * WT21 system to request flightplan from simbrief
     */
    class FmcFplnRequestSystem {
        /**
         * Ctor
         * @param fms Instance of the fms.
         */
        constructor(fms) {
            this.fms = fms;
            this.fmcUserSettings = FmcUserSettings.getManager(this.fms.bus);
        }
        /**
         * Requests the flightplan from simbrief.
         */
        async requestFlightplan() {
            const pilotId = this.fmcUserSettings.getSetting('simbriefPilotId').get();
            let ofp;
            let sbRte;
            try {
                ofp = await msfsSdk.SimbriefClient.getOfp(pilotId);
                sbRte = await msfsSdk.SimbriefDataExtraction.extractSimbriefRoute(ofp, this.fms.facLoader, msfsSdk.FacilityRepository.getRepository(this.fms.bus), () => {
                    const existingUserFacilities = this.fms.getUserFacilities();
                    return `U      ${WT21PilotWaypointUtils.nextAutoGeneratedName(existingUserFacilities, 'LL')}`;
                });
                this.fms.emptyModFlightPlan(true);
                const plan = this.fms.getModFlightPlan();
                this.fms.setOrigin(sbRte.originAirport);
                this.fms.performancePlanProxy.takeoffAirportIcao.set(sbRte.originAirport.icao);
                this.fms.setDestination(sbRte.destinationAirport);
                this.fms.performancePlanProxy.approachAirportIcao.set(sbRte.destinationAirport.icao);
                for (const segment of sbRte.enroute) {
                    if (segment.type === 'waypoint') {
                        const facility = await this.fms.facLoader.getFacility(msfsSdk.ICAO.getFacilityType(segment.icao), segment.icao);
                        this.fms.insertWaypoint(facility);
                    }
                    else {
                        const entryFacility = await this.fms.facLoader.getFacility(msfsSdk.FacilityType.Intersection, segment.entryFixIcao);
                        const exitFacility = await this.fms.facLoader.getFacility(msfsSdk.FacilityType.Intersection, segment.exitFixIcao);
                        const lastEnrouteSegmentIndex = this.fms.findLastEnrouteSegmentIndex(plan);
                        const newSegment = plan.insertSegment(lastEnrouteSegmentIndex + 1);
                        this.fms.insertAirwaySegment(segment.airwayObject, entryFacility, exitFacility, newSegment.segmentIndex, 0);
                    }
                }
                /*if (ofp.alternate) {
                  this.fms.setFlightPlanAlternate(sbRte.alternateAirport);
                }*/
                if (sbRte.flightNumber) {
                    this.fmcUserSettings.getSetting('flightNumber').set(sbRte.flightNumber);
                }
                this.fms.performancePlanProxy.cruiseAltitude.set(sbRte.cruiseLevel);
            }
            catch (e) {
                console.warn(`SB REQ FAIL: ${e}`);
                return false;
            }
            return true;
        }
    }

    class FplnRequestStatusFormat {
        constructor() {
            this.nullValueString = '';
        }
        /** @inheritDoc */
        format(value) {
            return value === false ? '' : 'REQ PENDING';
        }
    }
    class SimBriefPage extends FmcPage {
        constructor() {
            super(...arguments);
            this.fmcUserSettings = FmcUserSettings.getManager(this.eventBus);
            this.isRequestPending = msfsSdk.Subject.create(false);
            this.flpnDlStatus = msfsSdk.Subject.create("");
            this.fplnRecallField = new DisplayField(this, {
                formatter: RawFormatter,
                onSelected: () => this.fplnRecallPressed(),
            });
            this.fmcFplnRequestSystem = new FmcFplnRequestSystem(this.fms);
            this.fplnRequestStatusField = new DisplayField(this, {
                formatter: new FplnRequestStatusFormat(),
                style: '[green]'
            }).bind(this.isRequestPending);
            this.fplnDlStatusField = new DisplayField(this, {
                formatter: RawFormatter,
                style: '[green]'
            }).bind(this.flpnDlStatus);
            this.navLink = PageLinkField.createLink(this, '<INDEX', '/index');
            this.simbriefUsernameField = new TextInputField(this, {
                formatter: {
                    nullValueString: '---------',
                    /** @inheritDoc */
                    format(value) {
                        return value === -1 ? this.nullValueString : value.toString() + "[blue]";
                    },
                    /** @inheritDoc */
                    async parse(input) {
                        if (input.trim().length === 0) {
                            return null;
                        }
                        // check if input is a number
                        if (/^\d+$/.test(input)) {
                            return parseInt(input);
                        }
                        let pilotId = null;
                        try {
                            pilotId = await msfsSdk.SimbriefClient.getSimbriefUserIDFromUsername(input);
                        }
                        catch (error) {
                            return Promise.reject('INVALID SB USER');
                        }
                        return pilotId;
                    }
                },
                onModified: async (pilotId) => {
                    this.fmcUserSettings.getSetting('simbriefPilotId').set(pilotId);
                    return true;
                },
                onDelete: async () => {
                    this.fmcUserSettings.getSetting('simbriefPilotId').set(-1);
                    return true;
                },
            }).bind(this.fmcUserSettings.getSetting('simbriefPilotId'));
        }
        onInit() {
            this.fplnRecallField.takeValue('FPLN RECALL>');
        }
        async fplnRecallPressed() {
            if (this.isRequestPending.get() === false) {
                this.fplnRecallField.getOptions().disabled = true;
                this.isRequestPending.set(true);
                const success = await this.fmcFplnRequestSystem.requestFlightplan();
                this.fplnRecallField.getOptions().disabled = false;
                this.isRequestPending.set(false);
                if (success) {
                    this.fms.messageService.post(FMS_MESSAGE_ID.DLFPLNLOADED);
                    this.fplnDlStatusField.getOptions().style = '[green]';
                    this.fplnDlStatusField.takeValue("DL LOADED");
                    this.router.navigateTo('/route');
                }
                else {
                    this.fplnDlStatusField.getOptions().style = '[yellow]';
                    this.fms.messageService.post(FMS_MESSAGE_ID.DLFPLNFAIL);
                    this.fplnDlStatusField.takeValue("DL FAILED");
                    this.fms.cancelMod();
                }
            }
            return true;
        }
        /** @inheritDoc */
        render() {
            return [
                [
                    ['', '', 'SIMBRIEF[white]'],
                    [' SIMBRIEF ID', ''],
                    [this.simbriefUsernameField, ''],
                    ['', ''],
                    ['', ''],
                    ['', ''],
                    [this.fplnDlStatusField, this.fplnRequestStatusField],
                    [this.navLink, this.fplnRecallField]
                ]
            ];
        }
    }

    class LightBleed {
        constructor(bus, isFmc = false) {
            this.bus = bus;
            const subCustom = this.bus.getSubscriber();
            subCustom.on('screen_light_bleed').handle(() => this.toggleLcdCrt(isFmc));
        }
        toggleLcdCrt(isFmc) {
            const isCrt = SimVar.GetSimVarValue('L:VTX_C750_SCREEN_CRT', 'Bool');
            const elements = document.getElementsByClassName('lightBleed');
            const classToAdd = isFmc ? 'light-bleed-border-fmc' : 'light-bleed-border';
            const classToAdd2 = isCrt ? 'lightBleed-crt' : 'lightBleed-lcd';
            const classToRemove = isCrt ? 'lightBleed-lcd' : 'lightBleed-crt';
            if (isCrt) {
                for (let i = 0; i < elements.length; i++) {
                    elements[i].classList.remove(classToRemove);
                    elements[i].classList.remove(classToAdd);
                    elements[i].classList.add(classToAdd2);
                }
            }
            else {
                for (let i = 0; i < elements.length; i++) {
                    elements[i].classList.remove(classToRemove);
                    elements[i].classList.add(classToAdd);
                    elements[i].classList.add(classToAdd2);
                }
            }
        }
    }

